const body = $json.body || {};
const headers = $json.headers || {};
const message = body.message || body.conversation?.messages?.[0] || {};
const senderType = message.sender_type || message.sender?.type || '';
const labels = Array.isArray(body.conversation?.labels) ? body.conversation.labels.map(String) : [];
const attachments = Array.isArray(message.attachments)
  ? message.attachments.map(a => ({
      id: String(a.id || ''),
      fileType: String(a.file_type || ''),
      dataUrl: String(a.data_url || ''),
      fileSize: Number(a.file_size || 0),
    })).filter(a => a.id && a.dataUrl)
  : [];
const accepted = body.event === 'message_created'
  && senderType === 'Contact'
  && !labels.includes('intervencion-humana');
return [{
  json: {
    accepted,
    delivery: String(headers['x-chatwoot-delivery'] || message.source_id || message.id || ''),
    accountId: String(body.account?.id || ''),
    inboxId: String(body.inbox?.id || body.conversation?.inbox_id || ''),
    conversationId: String(message.conversation_id || body.conversation?.id || ''),
    contactId: String(body.conversation?.meta?.sender?.id || body.sender?.id || ''),
    phone: String(body.conversation?.meta?.sender?.phone_number || body.sender?.phone_number || ''),
    messageId: String(message.id || message.source_id || ''),
    content: String(message.content || body.content || ''),
    attachments,
  },
}];

const source = $('Normalize Incoming Message').first().json;
const queued = Array.isArray($('Read Queue').first().json.queuedMessages) ? $('Read Queue').first().json.queuedMessages : [];
const parsed = queued.map(value => { try { return JSON.parse(value); } catch { return null; } }).filter(Boolean);
const text = parsed.map(message => String(message.content || '').trim()).filter(Boolean).join('\n');
const attachmentRefs = parsed.flatMap(message =>
  (Array.isArray(message.attachments) ? message.attachments : []).map(attachment => ({
    messageId: String(message.messageId || ''),
    attachmentId: String(attachment.id || ''),
    fileType: String(attachment.fileType || ''),
    dataUrl: String(attachment.dataUrl || ''),
  }))
).filter(attachment => attachment.attachmentId && attachment.dataUrl);
const firstAttachment = attachmentRefs[0] || null;
const rawType = String(firstAttachment?.fileType || '').toLowerCase();
const messageType = rawType.includes('audio') ? 'audio' : rawType.includes('image') ? 'image' : 'text';
return [{ json: {
  ...source,
  content: text,
  messageIds: parsed.map(message => String(message.messageId || '')).filter(Boolean),
  attachmentRefs,
  messageType,
  messageMedia: firstAttachment?.dataUrl || '',
} }];

const source = $('Preparar contenido multimodal').first().json;
const text = String(source.content || '').trim();
let consent = null;
try { consent = typeof $json.consentState === 'string' ? JSON.parse($json.consentState) : $json.consentState; } catch { consent = null; }
let newConsent = false;
if (/^ACEPTO CONFIDENCIAL[.!]?$/i.test(text)) { consent = { mode: 'Confidencial', noticeVersion: 'whatsapp-sandbox-v2', acceptedAt: new Date().toISOString() }; newConsent = true; }
if (/^ACEPTO IDENTIFICADA[.!]?$/i.test(text)) { consent = { mode: 'Con identidad registrada', noticeVersion: 'whatsapp-sandbox-v2', acceptedAt: new Date().toISOString() }; newConsent = true; }
const explicitConfirmation = /^(CONFIRMO|CONFIRMO EL EXPEDIENTE FICTICIO)[.!]?$/i.test(text);
return [{ json: { ...source, consent, newConsent, explicitConfirmation } }];

const item = $('Consent and Confirmation Guard').first().json;
const text = String(item.content || '').toLowerCase();
const explicitDanger = /(peligro (inmediato|ahora)|est[aá]n pegando|lo est[aá]n golpeando|cagando a palo|dando una paliza|agresi[oó]n en curso|se est[aá] incendiando|incendio|no respira|intento de suicidio|amenaza con matar|arma|emergencia m[eé]dica)/i.test(text);
return [{ json: { ...item, immediateRisk: false, emergencyAdvisory: explicitDanger } }];

