const raw = $json.output && typeof $json.output === 'object' ? $json.output : {};
const reportInput = raw.draftPatch?.report && typeof raw.draftPatch.report === 'object' ? raw.draftPatch.report : {};
const text = (value, max = 6000) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const list = (value, max = 30) => Array.isArray(value) ? value.filter(item => typeof item === 'string').map(item => text(item, 500)).filter(Boolean).slice(0, max) : [];
const allowedActions = new Set(['continue','anonymous_web','human_handoff','create_case','case_created','stop']);
